// =============================================================================
// LOGINPAGE.JSX - PÁGINA DE LOGIN/REGISTRO (RESPETANDO CSS ORIGINAL)
// =============================================================================
// Este componente mantiene EXACTAMENTE la misma estructura HTML y clases CSS
// que tu diseño original, solo actualiza la lógica para usar AuthContext.
// =============================================================================

import React, { useState } from 'react';
import { useAuth } from './AuthContext';
import './css/login.css'; // Importar tu CSS original

/**
 * COMPONENTE: LoginPage
 * Mantiene la estructura HTML original con el efecto de tarjeta flip
 */
const LoginPage = ({ onBackToHome, onLoginSuccess }) => {

    // Estado para controlar el toggle entre login y registro
    const [isRegisterActive, setIsRegisterActive] = useState(false);

    // Funciones para cambiar entre vistas
    const switchToRegister = () => {
        setIsRegisterActive(true);
    };

    const switchToLogin = () => {
        setIsRegisterActive(false);
    };

    return (
        <>
            {/* FONDO */}
            <div className="background"></div>

            {/* LOGO HEADER */}
            <center>
                <a 
                    href="#" 
                    onClick={(e) => {
                        e.preventDefault();
                        onBackToHome();
                    }}
                    style={{ textDecoration: 'none' }}
                >
                    <h1 className="logo-header">FoamWash</h1>
                </a>
            </center>

            {/* CONTENEDOR PRINCIPAL */}
            <div className="container">
                {/* TARJETA CON EFECTO FLIP */}
                <div className={`card-wrapper ${isRegisterActive ? 'register-active' : ''}`}>

                    {/* ============================================= */}
                    {/* LADO IZQUIERDO: FORMULARIOS                  */}
                    {/* ============================================= */}
                    <div className="card-side form-side">

                        {/* VISTA DE LOGIN */}
                        {!isRegisterActive && (
                            <LoginView onLoginSuccess={onLoginSuccess} />
                        )}

                        {/* VISTA DE REGISTRO */}
                        {isRegisterActive && (
                            <RegisterView onLoginSuccess={onLoginSuccess} />
                        )}
                    </div>

                    {/* ============================================= */}
                    {/* LADO DERECHO: TOGGLE/MENSAJES                */}
                    {/* ============================================= */}
                    <div className="card-side toggle-side">

                        {/* CONTENIDO CUANDO LOGIN ESTÁ ACTIVO */}
                        <div className={`toggle-content login-active-content ${!isRegisterActive ? 'active' : ''}`}>
                            <h2 className="toggle-title">¡Hola amig@!</h2>

                            <p className="toggle-text">
                                Si no tienes una cuenta<br />
                                puedes crear una nueva
                            </p>

                            <button 
                                className="toggle-button" 
                                onClick={switchToRegister}
                            >
                                Registrar
                            </button>
                        </div>

                        {/* CONTENIDO CUANDO REGISTRO ESTÁ ACTIVO */}
                        <div className={`toggle-content register-active-content ${isRegisterActive ? 'active' : ''}`}>
                            <h2 className="toggle-title">¡Bienvenido de nuevo!</h2>

                            <p className="toggle-text">
                                Si ya tienes una cuenta<br />
                                puedes iniciar sesión
                            </p>

                            <button 
                                className="toggle-button" 
                                onClick={switchToLogin}
                            >
                                Iniciar sesión
                            </button>
                        </div>
                    </div>

                </div>
            </div>
        </>
    );
};

// =============================================================================
// COMPONENTE: LoginView (RESPETANDO CLASES CSS ORIGINALES)
// =============================================================================
const LoginView = ({ onLoginSuccess }) => {
    const { login } = useAuth();

    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [message, setMessage] = useState({ 
        text: '', 
        isError: false, 
        isLoading: false 
    });

    const handleLogin = (e) => {
        e.preventDefault();

        setMessage({ text: '', isError: false, isLoading: true });

        // Simular delay de red (puedes quitarlo en producción)
        setTimeout(() => {
            const result = login(email, password);

            if (result.success) {
                // ✅ LOGIN EXITOSO
                setMessage({ 
                    text: result.message, 
                    isError: false, 
                    isLoading: false 
                });

                // Esperar 1.5 segundos antes de redirigir
                setTimeout(() => {
                    if (onLoginSuccess) {
                        onLoginSuccess(result.role);
                    }
                }, 1500);

            } else {
                // ❌ LOGIN FALLIDO
                setMessage({ 
                    text: result.message, 
                    isError: true, 
                    isLoading: false 
                });
            }
        }, 500);
    };

    return (
        <div className="form-content login-view">
            <h2 className="title">Iniciar sesión</h2>

            {/* MENSAJES DE ESTADO */}
            {message.text && (
                <div className={`message-area ${message.isError ? 'error-message' : 'success-message'}`}>
                    {message.isLoading ? 'Cargando...' : message.text}
                </div>
            )}

            {/* FORMULARIO */}
            <form className="form" onSubmit={handleLogin}>

                {/* INPUT DE EMAIL */}
                <div className="input-group">
                    <input 
                        type="email" 
                        className="input-field" 
                        placeholder="Correo electrónico" 
                        required
                        autoComplete="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                    />
                </div>

                {/* INPUT DE CONTRASEÑA */}
                <div className="input-group">
                    <input 
                        type="password" 
                        className="input-field" 
                        placeholder="Contraseña" 
                        required
                        autoComplete="current-password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                    />
                </div>

                {/* ENLACE "OLVIDASTE TU CONTRASEÑA" */}
                <div className="forgot-password">
                    <a href="#" className="forgot-link">¿Olvidaste tu contraseña?</a>
                </div>

                {/* BOTÓN DE ENVÍO */}
                <button 
                    type="submit" 
                    className="submit-button"
                    disabled={message.isLoading}
                >
                    {message.isLoading ? 'Cargando...' : 'Iniciar sesión'}
                </button>
            </form>
        </div>
    );
};

// =============================================================================
// COMPONENTE: RegisterView (RESPETANDO CLASES CSS ORIGINALES)
// =============================================================================
const RegisterView = ({ onLoginSuccess }) => {
    const { register } = useAuth();

    const [email, setEmail] = useState('');
    const [fullName, setFullName] = useState('');
    const [phone, setPhone] = useState('');
    const [address, setAddress] = useState('');
    const [password, setPassword] = useState('');
    const [message, setMessage] = useState({ 
        text: '', 
        isError: false, 
        isLoading: false 
    });

    const handleRegister = (e) => {
        e.preventDefault();

        setMessage({ text: '', isError: false, isLoading: true });

        // Validaciones adicionales
        if (phone && phone.length !== 10) {
            setMessage({ 
                text: 'El teléfono debe tener exactamente 10 dígitos.', 
                isError: true, 
                isLoading: false 
            });
            return;
        }

        if (phone && !/^\d+$/.test(phone)) {
            setMessage({ 
                text: 'El teléfono solo puede contener números.', 
                isError: true, 
                isLoading: false 
            });
            return;
        }

        // Simular delay de red
        setTimeout(() => {
            const result = register(email, password, fullName, phone, address);

            if (result.success) {
                // ✅ REGISTRO EXITOSO
                setMessage({ 
                    text: result.message, 
                    isError: false, 
                    isLoading: false 
                });

                // Esperar 1.5 segundos antes de redirigir
                setTimeout(() => {
                    if (onLoginSuccess) {
                        onLoginSuccess(result.role);
                    }
                }, 1500);

            } else {
                // ❌ REGISTRO FALLIDO
                setMessage({ 
                    text: result.message, 
                    isError: true, 
                    isLoading: false 
                });
            }
        }, 1000);
    };

    return (
        <div className="form-content register-view">
            <h2 className="title">Regístrate</h2>

            {/* MENSAJES DE ESTADO */}
            {message.text && (
                <div className={`message-area ${message.isError ? 'error-message' : 'success-message'}`}>
                    {message.isLoading ? 'Procesando...' : message.text}
                </div>
            )}

            {/* FORMULARIO */}
            <form className="form" onSubmit={handleRegister}>

                {/* INPUT DE EMAIL */}
                <div className="input-group">
                    <input 
                        type="email" 
                        className="input-field" 
                        placeholder="Correo electrónico *" 
                        required
                        autoComplete="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                    />
                </div>

                {/* INPUT DE NOMBRE COMPLETO */}
                <div className="input-group">
                    <input 
                        type="text" 
                        className="input-field" 
                        placeholder="Nombre completo *" 
                        required
                        autoComplete="name"
                        value={fullName}
                        onChange={(e) => setFullName(e.target.value)}
                    />
                </div>

                {/* INPUT DE TELÉFONO */}
                <div className="input-group">
                    <input 
                        type="tel" 
                        className="input-field" 
                        placeholder="Teléfono (10 dígitos) *" 
                        required
                        pattern="[0-9]{10}"
                        autoComplete="tel"
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                    />
                </div>

                {/* INPUT DE DIRECCIÓN (OPCIONAL) */}
                <div className="input-group">
                    <input 
                        type="text" 
                        className="input-field" 
                        placeholder="Dirección (opcional)" 
                        autoComplete="street-address"
                        value={address}
                        onChange={(e) => setAddress(e.target.value)}
                    />
                </div>

                {/* INPUT DE CONTRASEÑA */}
                <div className="input-group">
                    <input 
                        type="password" 
                        className="input-field" 
                        placeholder="Contraseña (mín. 6 caracteres) *" 
                        required
                        autoComplete="new-password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                    />
                </div>

                {/* BOTÓN DE ENVÍO */}
                <button 
                    type="submit" 
                    className="submit-button register-submit"
                    disabled={message.isLoading}
                >
                    {message.isLoading ? 'Procesando...' : 'Registrar'}
                </button>
            </form>
        </div>
    );
};

export default LoginPage;

